"""Configuration schema, JSON loader, and data-driven tool registry for global agent-files sync."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Sequence

DEFAULT_CONFIG_FILENAME = "agent-files.json"
DEFAULT_DIGEST_RELPATH = "guidelines/agent-digest.md"
DEFAULT_SKILLS_RELPATH = "skills"
DEFAULT_MARKER = "dev-guidelines"
DEFAULT_MARKER_BEGIN = (
    "<!-- BEGIN dev-guidelines (auto-generated by update-global-agent-files.py -- do not edit by "
    "hand; edit guidelines/agent-digest.md in the dev-guidelines repo instead) -->"
)
DEFAULT_MARKER_END = "<!-- END dev-guidelines -->"
DEFAULT_MANIFEST_SOURCE = "dev-guidelines"
DEFAULT_MANIFEST_NAME = ".dev-guidelines-skills.json"
DEFAULT_LEGACY_SKILL_NAMES: tuple[str, ...] = ("plan-task-usage", "ui-verification")

_ALLOWED_CONFIG_KEYS = frozenset(
    {
        "repo_root",
        "digest_path",
        "digest",
        "skills_dir",
        "skills",
        "marker",
        "marker_begin",
        "marker_end",
        "manifest_source",
        "manifest_name",
        "legacy_skill_names",
        "tools",
        "replace_tools",
    }
)
_ALLOWED_TOOL_KEYS = frozenset(
    {
        "name",
        "command",
        "target_file",
        "review_args",
        "fallback_paths",
        "skills_dir",
        "native_skill_discovery",
        "legacy_skills_dirs",
        "bootstrap_skill_names",
        "aliases",
    }
)


def default_review_args(prompt: str, target_filename: str, timeout: int) -> list[str]:
    """Return empty default CLI arguments for headless review when none are configured."""
    return []


class ToolRegistry:
    """Data-driven registry of AI coding tools supporting lookup and selection by name or alias."""

    def __init__(self, tools: Sequence[Any] | None = None) -> None:
        """Initialize the registry with the given tools, or the built-in defaults when None."""
        if tools is None:
            from support_python.tools.agent_files import TOOLS as default_tools

            tools = default_tools
        self._tools: list[Any] = list(tools)

    def register(self, tool: Any) -> None:
        """Add a tool to the registry or replace an existing entry matching its name or alias."""
        keys = {tool.name, *getattr(tool, "aliases", ())}
        for idx, existing in enumerate(self._tools):
            if keys & ({existing.name, *getattr(existing, "aliases", ())}):
                self._tools[idx] = tool
                return
        self._tools.append(tool)

    def get(self, name: str) -> Any | None:
        """Return the tool matching name or alias, or None if not registered."""
        for tool in self._tools:
            if name == tool.name or name in getattr(tool, "aliases", ()):
                return tool
        return None

    def list(self) -> list[Any]:
        """Return all registered tools in registration order."""
        return list(self._tools)

    def names(self) -> list[str]:
        """Return canonical names of all registered tools."""
        return [tool.name for tool in self._tools]

    def select(self, tool_names: Sequence[str]) -> list[Any]:
        """Return tools matching tool_names in registry order, or all tools when tool_names is empty."""
        if not tool_names:
            return list(self._tools)
        resolved = {self.get(name).name for name in tool_names if self.get(name) is not None}
        return [tool for tool in self._tools if tool.name in resolved]


@dataclass(frozen=True)
class AgentFilesConfig:
    """Resolved configuration for deterministic global agent-files and skills synchronization."""

    repo_root: Path
    digest_path: Path
    skills_dir: Path
    marker: str = DEFAULT_MARKER
    marker_begin: str = DEFAULT_MARKER_BEGIN
    marker_end: str = DEFAULT_MARKER_END
    manifest_source: str = DEFAULT_MANIFEST_SOURCE
    manifest_name: str = DEFAULT_MANIFEST_NAME
    legacy_skill_names: tuple[str, ...] = DEFAULT_LEGACY_SKILL_NAMES
    tools: tuple[Any, ...] = ()


def resolve_markers(
    marker: str = DEFAULT_MARKER,
    marker_begin: str | None = None,
    marker_end: str | None = None,
) -> tuple[str, str, str]:
    """Resolve marker identifier and guarded block begin/end marker lines."""
    if not isinstance(marker, str) or not marker.strip():
        raise ValueError("'marker' must be a non-empty string")
    clean = marker.strip()
    if marker_begin is not None and (not isinstance(marker_begin, str) or not marker_begin.strip()):
        raise ValueError("'marker_begin' must be a non-empty string")
    if marker_end is not None and (not isinstance(marker_end, str) or not marker_end.strip()):
        raise ValueError("'marker_end' must be a non-empty string")
    begin = (
        marker_begin.strip() if marker_begin else (DEFAULT_MARKER_BEGIN if clean == DEFAULT_MARKER else f"<!-- BEGIN {clean} -->")
    )
    end = marker_end.strip() if marker_end else (DEFAULT_MARKER_END if clean == DEFAULT_MARKER else f"<!-- END {clean} -->")
    return clean, begin, end


def _validate_str_list(value: Any, field_name: str) -> tuple[str, ...]:
    if not isinstance(value, list) or not all(isinstance(item, str) and item.strip() for item in value):
        raise ValueError(f"'{field_name}' must be a list of non-empty strings")
    return tuple(item.strip() for item in value)


def build_tool_from_dict(data: dict[str, Any], default_legacy_skills: tuple[str, ...] = ()) -> Any:
    """Validate and construct a Tool instance from a JSON dictionary definition."""
    from support_python.tools.agent_files import Tool

    if not isinstance(data, dict) or (set(data.keys()) - _ALLOWED_TOOL_KEYS):
        raise ValueError("invalid tool definition object or unknown keys")
    for req in ("name", "command", "target_file"):
        if not isinstance(data.get(req), str) or not data[req].strip():
            raise ValueError(f"tool definition requires non-empty string '{req}'")
    skills_raw = data.get("skills_dir")
    if skills_raw is not None and (not isinstance(skills_raw, str) or not skills_raw.strip()):
        raise ValueError("tool 'skills_dir' must be a non-empty string or null")
    native = data.get("native_skill_discovery", False)
    if not isinstance(native, bool):
        raise ValueError("tool 'native_skill_discovery' must be a boolean")
    raw_review = data.get("review_args")
    review_tpl = list(_validate_str_list(raw_review, "review_args")) if raw_review is not None else None
    review_fn: Callable[[str, str, int], list[str]] = (
        default_review_args
        if review_tpl is None
        else lambda p, t, to: [arg.format(prompt=p, target_file=t, timeout=to) for arg in review_tpl]
    )
    bootstrap = (
        _validate_str_list(data["bootstrap_skill_names"], "bootstrap_skill_names")
        if "bootstrap_skill_names" in data
        else default_legacy_skills
    )
    return Tool(
        name=data["name"].strip(),
        command=data["command"].strip(),
        target_file=Path(data["target_file"]).expanduser(),
        review_args=review_fn,
        fallback_paths=tuple(Path(p).expanduser() for p in _validate_str_list(data.get("fallback_paths", []), "fallback_paths")),
        skills_dir=Path(skills_raw).expanduser() if skills_raw else None,
        native_skill_discovery=native,
        legacy_skills_dirs=tuple(
            Path(p).expanduser() for p in _validate_str_list(data.get("legacy_skills_dirs", []), "legacy_skills_dirs")
        ),
        bootstrap_skill_names=bootstrap,
        aliases=_validate_str_list(data.get("aliases", []), "aliases"),
    )


def _resolve_path(base: Path, raw: str | Path) -> Path:
    candidate = Path(raw).expanduser()
    return candidate if candidate.is_absolute() else (base / candidate).resolve()


def _read_and_validate_json(path: Path) -> dict[str, Any]:
    try:
        parsed = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"Invalid JSON in {path}: {exc}") from exc
    if not isinstance(parsed, dict) or (set(parsed.keys()) - _ALLOWED_CONFIG_KEYS):
        raise ValueError(f"Invalid configuration schema in {path}")
    return parsed


def load_agent_files_config(
    config_path: Path | str | None = None,
    *,
    repo_root: Path | str | None = None,
    digest_path: Path | str | None = None,
    skills_dir: Path | str | None = None,
    marker: str | None = None,
    marker_begin: str | None = None,
    marker_end: str | None = None,
    manifest_source: str | None = None,
    manifest_name: str | None = None,
    legacy_skill_names: Sequence[str] | None = None,
    base_tools: Sequence[Any] | None = None,
) -> AgentFilesConfig:
    """Load, validate, and resolve agent-files sync settings from JSON and explicit overrides."""
    from support_python.tools.agent_files import TOOLS as default_tools, find_project_root

    raw: dict[str, Any] = {}
    cfg_dir: Path | None = None
    if config_path is not None:
        resolved_cfg = Path(config_path).expanduser().resolve()
        if not resolved_cfg.is_file():
            raise FileNotFoundError(f"Configuration file not found: {resolved_cfg}")
        cfg_dir, raw = resolved_cfg.parent, _read_and_validate_json(resolved_cfg)
    else:
        init_root = Path(repo_root).expanduser().resolve() if repo_root is not None else find_project_root()
        candidate = init_root / DEFAULT_CONFIG_FILENAME
        if candidate.is_file():
            cfg_dir, raw = candidate.parent, _read_and_validate_json(candidate)

    if repo_root is not None:
        resolved_root = Path(repo_root).expanduser().resolve()
    elif "repo_root" in raw:
        if not isinstance(raw["repo_root"], str) or not raw["repo_root"].strip():
            raise ValueError("'repo_root' must be a non-empty string")
        resolved_root = _resolve_path(cfg_dir or Path.cwd(), raw["repo_root"])
    else:
        resolved_root = cfg_dir.resolve() if cfg_dir is not None else find_project_root()

    raw_digest = digest_path if digest_path is not None else raw.get("digest_path", raw.get("digest"))
    if raw_digest is not None and (not isinstance(raw_digest, (str, Path)) or not str(raw_digest).strip()):
        raise ValueError("'digest_path' must be a non-empty path string")
    resolved_digest = _resolve_path(resolved_root, raw_digest) if raw_digest is not None else resolved_root / DEFAULT_DIGEST_RELPATH

    raw_skills = skills_dir if skills_dir is not None else raw.get("skills_dir", raw.get("skills"))
    if raw_skills is not None and (not isinstance(raw_skills, (str, Path)) or not str(raw_skills).strip()):
        raise ValueError("'skills_dir' must be a non-empty path string")
    resolved_skills = _resolve_path(resolved_root, raw_skills) if raw_skills is not None else resolved_root / DEFAULT_SKILLS_RELPATH

    resolved_marker, resolved_begin, resolved_end = resolve_markers(
        marker=marker if marker is not None else raw.get("marker", DEFAULT_MARKER),
        marker_begin=marker_begin if marker_begin is not None else raw.get("marker_begin"),
        marker_end=marker_end if marker_end is not None else raw.get("marker_end"),
    )
    raw_source = manifest_source if manifest_source is not None else raw.get("manifest_source", DEFAULT_MANIFEST_SOURCE)
    if not isinstance(raw_source, str) or not raw_source.strip():
        raise ValueError("'manifest_source' must be a non-empty string")
    resolved_source = raw_source.strip()

    raw_mname = manifest_name if manifest_name is not None else raw.get("manifest_name")
    if raw_mname is not None and (not isinstance(raw_mname, str) or not raw_mname.strip()):
        raise ValueError("'manifest_name' must be a non-empty string")
    resolved_mname = (
        raw_mname.strip()
        if raw_mname is not None
        else (DEFAULT_MANIFEST_NAME if resolved_source == DEFAULT_MANIFEST_SOURCE else f".{resolved_source}-skills.json")
    )
    if legacy_skill_names is not None:
        resolved_legacy = tuple(legacy_skill_names)
    elif "legacy_skill_names" in raw:
        resolved_legacy = _validate_str_list(raw["legacy_skill_names"], "legacy_skill_names")
    else:
        resolved_legacy = DEFAULT_LEGACY_SKILL_NAMES if resolved_source == DEFAULT_MANIFEST_SOURCE else ()

    replace_tools = raw.get("replace_tools", False)
    if not isinstance(replace_tools, bool):
        raise ValueError("'replace_tools' must be a boolean")
    registry = ToolRegistry([] if replace_tools else (base_tools if base_tools is not None else default_tools))
    if "tools" in raw:
        raw_tools = raw["tools"]
        if isinstance(raw_tools, dict):
            entries = [{"name": k, **v} if isinstance(v, dict) else v for k, v in raw_tools.items()]
        elif isinstance(raw_tools, list):
            entries = raw_tools
        else:
            raise ValueError("'tools' must be a list or object of tool definitions")
        for entry in entries:
            registry.register(build_tool_from_dict(entry, default_legacy_skills=resolved_legacy))

    return AgentFilesConfig(
        repo_root=resolved_root,
        digest_path=resolved_digest,
        skills_dir=resolved_skills,
        marker=resolved_marker,
        marker_begin=resolved_begin,
        marker_end=resolved_end,
        manifest_source=resolved_source,
        manifest_name=resolved_mname,
        legacy_skill_names=resolved_legacy,
        tools=tuple(registry.list()),
    )
